import React, { useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import './Profile.css';

const Profile = () => {
  const { currentUser } = useAuth();
  const [userData, setUserData] = useState(null);
  const [newUsername, setNewUsername] = useState('');
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  useEffect(() => {
    if (currentUser) {
      fetch(`https://localhost:7051/Felhasznalo/profile/${currentUser.username}`)
        .then((response) => response.json())
        .then((data) => {
          setUserData(data);
          setNewUsername(data.username); // Alapértelmezett érték
        })
        .catch((error) => console.error('Error fetching user profile:', error));
    }
  }, [currentUser]);

  const handleUpdateProfile = async (e) => {
    e.preventDefault();

    const requestBody = {
      username: newUsername,
      currentPassword: currentPassword,
      newPassword: newPassword,
    };

    try {
      const response = await fetch(`https://localhost:7051/User/${currentUser.username}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      });

      if (response.ok) {
        setSuccessMessage('Profil sikeresen frissítve!');
        setErrorMessage('');
        setCurrentPassword('');
        setNewPassword('');
      } else {
        const data = await response.json();
        setErrorMessage(data.message || 'Hiba történt a frissítés során.');
        setSuccessMessage('');
      }
    } catch (error) {
      setErrorMessage('Hiba történt a frissítés során.');
      setSuccessMessage('');
    }
  };

  if (!currentUser) {
    return <div>Kérlek jelentkezz be a profilod megtekintéséhez.</div>;
  }

  return (
    <div className="profile-container">
      <h2>Profil</h2>
      {userData ? (
        <form onSubmit={handleUpdateProfile} className="profile-form">
          <div className="form-group">
            <label htmlFor="username">Felhasználónév</label>
            <input
              type="text"
              id="username"
              value={newUsername}
              onChange={(e) => setNewUsername(e.target.value)}
              className="form-control"
            />
          </div>
          <div className="form-group">
            <label htmlFor="currentPassword">Jelenlegi jelszó</label>
            <input
              type="password"
              id="currentPassword"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              className="form-control"
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="newPassword">Új jelszó</label>
            <input
              type="password"
              id="newPassword"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="form-control"
            />
          </div>
          <button type="submit" className="btn btn-primary">
            Frissítés
          </button>
          {successMessage && <p className="success-message">{successMessage}</p>}
          {errorMessage && <p className="error-message">{errorMessage}</p>}
        </form>
      ) : (
        <p>Betöltés...</p>
      )}
    </div>
  );
};

export default Profile;
